if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_iptables_chain() {
    _helper_iptables_chains
}

_choice_iptables_delete() {
    case "${#argc_delete[@]}" in
    1) _helper_iptables_chains ;;
    2) _helper_iptables_rulenum "${argc_delete[0]}" ;;
    esac
}

_choice_iptables_delete_chain() {
    _helper_iptables_user_chains
}

_choice_iptables_goto() {
    _helper_iptables_user_chains
}

_choice_iptables_insert() {
    case "${#argc_insert[@]}" in
    1) _helper_iptables_chains ;;
    2) _helper_iptables_rulenum "${argc_insert[0]}" ;;
    esac
}

_choice_iptables_interface() {
    if [[ -d /sys/class/net ]]; then
        find /sys/class/net -mindepth 1 -maxdepth 1 -print 2>/dev/null | gawk -F/ '{ print $NF }'
    fi
}

_choice_iptables_match() {
    printf '%s\n' addrtype ah bpf cgroup cluster comment connbytes connlabel connlimit connmark conntrack cpu dccp devgroup dscp dst ecn esp eui64 frag hashlimit hbh helper hl icmp icmp6 iprange ipv6header ipvs length limit mac mark mh multiport nfacct osf owner physdev pkttype policy quota rateest realm recent rpfilter rt sctp set socket state statistic string tcp tcpmss time tos ttl u32 udp
}

_choice_iptables_modprobe() {
    _argc_util_comp_command
}

_choice_iptables_policy() {
    if [[ "${#argc_policy[@]}" -le 1 ]]; then
        _helper_iptables_builtin_chains
    else
        printf '%s\n' ACCEPT DROP
    fi
}

_choice_iptables_protocol() {
    printf '%s\n' tcp udp udplite icmp icmpv6 esp ah sctp mh all
    if [[ -r /etc/protocols ]]; then
        gawk '$1 !~ /^#/ && NF >= 2 { print $1 }' /etc/protocols
    fi
}

_choice_iptables_rename_chain() {
    if [[ "${#argc_rename_chain[@]}" -le 1 ]]; then
        _helper_iptables_user_chains
    fi
}

_choice_iptables_replace() {
    case "${#argc_replace[@]}" in
    1) _helper_iptables_chains ;;
    2) _helper_iptables_rulenum "${argc_replace[0]}" ;;
    esac
}

_choice_iptables_target() {
    printf '%s\n' ACCEPT DROP RETURN
    printf '%s\n' AUDIT CHECKSUM CLASSIFY CLUSTERIP CONNMARK CONNSECMARK CT DNAT DNPT DSCP ECN HL HMARK IDLETIMER LED LOG MARK MASQUERADE NETMAP NFLOG NFQUEUE NOTRACK RATEEST REDIRECT REJECT SECMARK SET SNAT SNPT SYNPROXY TCPMSS TCPOPTSTRIP TEE TOS TPROXY TRACE TTL ULOG
    _helper_iptables_user_chains
}

_choice_iptables_zero() {
    case "${#argc_zero[@]}" in
    1) _helper_iptables_chains ;;
    2) _helper_iptables_rulenum "${argc_zero[0]}" ;;
    esac
}

_helper_iptables_builtin_chains() {
    case "${argc_table:-filter}" in
    nat) printf '%s\n' PREROUTING INPUT OUTPUT POSTROUTING ;;
    mangle) printf '%s\n' PREROUTING INPUT FORWARD OUTPUT POSTROUTING ;;
    raw) printf '%s\n' PREROUTING OUTPUT ;;
    *) printf '%s\n' INPUT FORWARD OUTPUT ;;
    esac
}

_helper_iptables_chains() {
    _helper_iptables_builtin_chains
    _helper_iptables_user_chains
}

_helper_iptables_rulenum() {
    local chain=$1
    [[ -n "$chain" ]] || return 0
    iptables -t "${argc_table:-filter}" -L "$chain" --line-numbers -n 2>/dev/null \
        | gawk 'NR > 2 && $1 ~ /^[0-9]+$/ { print $1 "\t" $2 " " $3 " -- " $5 " " $6 }'
}

_helper_iptables_user_chains() {
    iptables -S -t "${argc_table:-filter}" 2>/dev/null | gawk '$1 == "-N" { print $2 }'
}
